('nokia-g56-pro-5g', 'Nokia G56 Pro 5G 8GB/256GB - Nordic Blue', 'smartphones', 185000, 179000, 152000, 42, 0.20, '/assets/products/nokia-g56-pro.jpg', 'Built on a legacy of trust with a promise of longevity. The G56 Pro delivers a pure Android experience with guaranteed 3 years of OS updates and 4 years of security patches, wrapped in a durable, IP52-rated body crafted from recycled materials.', 1, unixepoch('2026-06-16'), 1, 152000, '/assets/products/nokia-g56-pro.jpg', 168000, 4.4, 0, 'Nokia', 1, 1),

