('nothing-phone-cmf-2', 'Nothing CMF Phone 2 8GB/256GB - Orange', 'smartphones', 165000, 159000, 135000, 40, 0.20, '/assets/products/cmf-phone-2.jpg', 'Stripped-back brilliance from Nothing''s sub-brand. The CMF Phone 2 delivers a clean, customizable Android experience with a unique modular accessory system, a capable 50MP Sony sensor, and a vivid 120Hz AMOLED display that punches far above its price.', 1, unixepoch('2026-06-16'), 1, 135000, '/assets/products/cmf-phone-2.jpg', 149000, 4.5, 1, 'Nothing', 1, 1),

('blackview-bv9300-pro', 'Blackview BV9300 Pro Rugged Phone 12GB/256GB - Black/Green', 'smartphones', 245000, 239000, 202000, 25, 0.38, '/assets/products/blackview-bv9300-pro.jpg', 'Indestructible performance for Nigeria''s toughest environments. IP69K waterproof, MIL-STD-810H drop-proof, and featuring a massive 15,080mAh battery with reverse charging. The built-in 100-lumen flashlight and laser rangefinder make it essential for field professionals.', 1, unixepoch('2026-06-16'), 1, 202000, '/assets/products/blackview-bv9300-pro.jpg', 225000, 4.4, 0, 'Blackview', 1, 1),

('ulefone-armor-27t-pro', 'Ulefone Armor 27T Pro 5G Thermal Camera Rugged Phone', 'smartphones', 350000, 339000, 288000, 15, 0.41, '/assets/products/ulefone-armor-27t.jpg', 'A built-in FLIR thermal camera transforms this rugged phone into a professional diagnostic tool. Detecting heat leaks, electrical faults, and wildlife at night, combined with 5G connectivity and a 10,600mAh battery, makes it indispensable for engineers and adventurers alike.', 1, unixepoch('2026-06-16'), 1, 288000, '/assets/products/ulefone-armor-27t.jpg', 318000, 4.3, 0, 'Ulefone', 1, 1),

