('soundpeats-air5-pro', 'SoundPEATS Air5 Pro Snapdragon Sound LE Audio Earbuds', 'audio', 32000, 30900, 25800, 85, 0.04, '/assets/products/soundpeats-air5-pro.jpg', 'Audiophile wireless audio goes mainstream. The Air5 Pro supports Snapdragon Sound with aptX Lossless for CD-quality streaming, adaptive ANC, and LDAC hi-res audio, all in a compact, comfortable stem design that punches well above its weight.', 1, unixepoch('2026-06-16'), 1, 25800, '/assets/products/soundpeats-air5-pro.jpg', 29200, 4.6, 1, 'SoundPEATS', 1, 1),

