('fifine-ampligame-h9', 'FIFINE AmpliGame H9 Low-Latency Gaming Earbuds - RGB Black', 'audio', 12000, 11500, 9200, 130, 0.05, '/assets/products/fifine-h9.jpg', 'Victory sounds this good. Designed for mobile gamers, the H9 delivers 45ms ultra-low latency, a detachable boom mic for clear squad communication, and customizable RGB lighting on each earbud—dominate your matches in style.', 1, unixepoch('2026-06-16'), 1, 9200, '/assets/products/fifine-h9.jpg', 10800, 4.4, 0, 'FIFINE', 1, 1),

('tronsmart-onyx-a5', 'Tronsmart Onyx A5 Bone Conduction Open-Ear Earbuds', 'audio', 28000, 26900, 22500, 75, 0.06, '/assets/products/tronsmart-onyx-a5.jpg', 'Stay aware of your surroundings without sacrificing audio quality. The Onyx A5 uses advanced bone conduction technology with an air conduction woofer for rich bass, making them the safest choice for outdoor runners and commuters in busy Nigerian cities.', 1, unixepoch('2026-06-16'), 1, 22500, '/assets/products/tronsmart-onyx-a5.jpg', 25500, 4.4, 1, 'Tronsmart', 1, 1),

